// === Tab: Circle ===
class Circle {
	constructor(radius, incolor, orbitRadius, angularSpeed, parent, angle = 0) {
		this.radius = radius * 3;
		this.color = incolor;
		this.orbitRadius = orbitRadius;
		this.angularSpeed = angularSpeed;
		this.parent = parent;
		this.angle = angle;
		this.x = 0;
		this.y = 0;
		this.trail = [];
		this.maxTrailLength = 200;
		this.color2 = color(red(window.color(this.color)), green(window.color(this.color)), blue(window.color(this.color)), 100);
	}

	update(dt) {
		this.angle += this.angularSpeed * dt * speedMultiplier;

		if (this.parent) {
			this.x = this.parent.x + cos(this.angle) * this.orbitRadius;
			this.y = this.parent.y + sin(this.angle) * this.orbitRadius;
		} else {
			this.x = centerX;
			this.y = centerY;
		}

		this.trail.push({
			x: this.x,
			y: this.y
		});
		if (this.trail.length > this.maxTrailLength) {
			this.trail.shift();
		}
	}

	draw() {
		// Draw trail
		if (this.trail.length > 1) {
			stroke(this.color2);
			noFill();
			strokeWeight(2);
			beginShape();
			vertex(this.trail[0].x, this.trail[0].y);
			for (let i = 0; i < this.trail.length; i++) {
				vertex(this.trail[i].x, this.trail[i].y);
			}
			endShape();

		}

		// Draw orbit path (faint)
		if (this.parent) {
			stroke(this.color2);
			strokeWeight(1);
			//beginShape();
			arc(this.parent.x, this.parent.y, this.orbitRadius, this.orbitRadius, 0, TWO_PI);

		}

		// Draw circle
		fill(this.color);
		stroke('white');
		strokeWeight(2);
		circle(this.x, this.y, this.radius * 2);
	}

	getDistance(other) {
		const dx = this.x - other.x;
		const dy = this.y - other.y;
		return sqrt(dx * dx + dy * dy);
	}

	isColliding(other) {
		return this.getDistance(other) <= (this.radius + other.radius);
	}

	switchOrbit(newParent) {
		// Calculate new angle relative to new parent
		var dx = this.x - newParent.x;
		var dy = this.y - newParent.y;
		this.angle = atan2(dy, dx);
		//this.orbitRadius = sqrt(dx * dx + dy * dy);
		this.orbitRadius = this.radius + newParent.radius;
		this.parent = newParent;
	}
}

